fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digits"))
        .collect()
}

fn sim(n: u64) -> SimId {
    SimId::try_from(n).expect("valid")
}

/// The repository's data with the search height `c` of the market.
fn market_data(height: f64) -> Data {
    let (calibration, genome_map) = common::files();
    let mut demography = common::demography();
    demography["values"]["core:market_search_height_female"]["value"] = serde_json::json!(height);
    Data::new(common::definitions_with(demography, calibration, genome_map).expect("definitions"))
        .expect("checked")
}

fn market_start() -> Input {
    let founder = |years: i64, sex: Sex| Founder {
        born: SimTime::from_secs(-years * Y),
        sex,
        alleles: Vec::new(),
    };
    Input::Start(Start {
        world_seed: 0xff,
        founder_tag: DataId::new("test:market").expect("valid"),
        world_params: WorldParams {
            hereditary_diseases: false,
            nutrition: Vec::new(),
        },
        founders: vec![
            founder(20, Sex::Female),
            founder(24, Sex::Male),
            founder(21, Sex::Female),
            founder(25, Sex::Male),
            founder(22, Sex::Female),
            founder(23, Sex::Male),
            founder(20, Sex::Female),
            founder(21, Sex::Female),
            founder(25, Sex::Male),
            founder(40, Sex::Male),
        ],
        couples: vec![
            Couple { woman: 0, man: 1 },
            Couple { woman: 2, man: 3 },
            Couple { woman: 4, man: 5 },
        ],
        capacity: None,
        pool: None,
    })
}

struct Run {
    world: World,
    out: YearOut,
    log: Vec<LogEntry>,
}

impl Run {
    fn market() -> Run {
        let mut world = World::new(market_data(1.0));
        world.submit(market_start()).expect("accepted");
        let log = world.take_log();
        Run {
            world,
            out: YearOut::default(),
            log,
        }
    }

    fn advance(&mut self, until: i64) {
        self.world
            .advance_until(&mut self.out, SimTime::from_secs(until), &mut |_| false);
        self.log.extend(self.world.take_log());
    }

    fn save(&self) -> Vec<u8> {
        self.world.save(&self.out.year_hashes).expect("saves")
    }

    /// The partnerships formed so far as (woman, man, formed).
    fn pairs(&self) -> Vec<(u64, u64, i64)> {
        self.world
            .pedigree()
            .partnerships
            .iter()
            .map(|p| (p.woman.get(), p.man.get(), p.formed.as_secs()))
            .collect()
    }
}

#[test]
fn the_test_data_of_market() {
    assert_eq!(market_data(1.0).hash(), MARKET_DATA_HASH);
}

/// Round 1: the single women 7 and 8 both search, sim 8 first by her rank; both choose
/// sim 9. Sim 8 gets him (partnership 4, an entry with the plan of the round, the rule and
/// the noise of the chosen candidate as causes); sim 7 gets nobody and no second try. In
/// round 2 she chooses the man of 40, the only single man left.
#[test]
fn the_first_rounds_pair_the_single_founders() {
    let mut run = Run::market();
    run.advance(MONTH - 1);
    assert_eq!(run.save(), hex(MARKET_SAVE_BEFORE_PAIRING_ROUND));
    let before = run.log.len();
    run.advance(MONTH);
    // The partnership, its household and the two moves (ADR-0018 section 4).
    assert_eq!(run.log.len(), before + 4);
    assert_eq!(
        postcard::to_allocvec(&run.log[before]).expect("encodes"),
        hex(MARKET_PARTNERED_ENTRY)
    );
    assert_eq!(
        serde_json::to_string(&run.log[before]).expect("json"),
        PARTNERED_JSON
    );
    assert_eq!(run.save(), hex(MARKET_SAVE_AFTER_PAIRING_ROUND));
    run.advance(2 * MONTH);
    assert_eq!(
        run.pairs()[3..],
        [(8, 9, MONTH), (7, 10, 2 * MONTH)],
        "the couples of `Start` are partnerships 1 to 3"
    );
}

/// Round 478: the searching girl of 17 (sim 24) has her first cousin (sim 26, φ = 1/16,
/// the penalty ln 10) and a stranger (sim 27) in her list; she takes the stranger. The
/// woman of 31 before her (sim 23) skips both, her nephews (φ = 1/8), and finds nobody.
#[test]
fn a_cousin_in_the_list_pays_the_penalty() {
    let mut run = Run::market();
    run.advance(478 * MONTH - 1);
    assert_eq!(run.save(), hex(MARKET_SAVE_BEFORE_COUSIN_ROUND));
    let before = run.log.len();
    run.advance(478 * MONTH);
    assert_eq!(run.log.len(), before + 4);
    assert_eq!(
        postcard::to_allocvec(&run.log[before]).expect("encodes"),
        hex(MARKET_COUSIN_ROUND_ENTRY)
    );
    assert_eq!(
        serde_json::to_string(&run.log[before]).expect("json"),
        COUSIN_ROUND_JSON
    );
    assert_eq!(run.save(), hex(MARKET_SAVE_AFTER_COUSIN_ROUND));
}

/// Forty years of "market": 17 partnerships, among them the girl of 17 who skips her twin
/// brother (round 238, she pairs with sim 16) and the boy chosen on his 16th birthday
/// (round 502, sim 31 by sim 23); nobody is paired below 16.
#[test]
fn forty_years_of_market() {
    let mut run = Run::market();
    run.advance(40 * Y - 1);
    let pairs = run.pairs();
    assert_eq!(pairs.len(), 17);
    assert!(pairs.contains(&(14, 16, 238 * MONTH)));
    assert!(pairs.contains(&(23, 31, 502 * MONTH)));
    let born = |id: u64| run.world.state().born(sim(id)).expect("known").as_secs();
    assert!(
        pairs
            .iter()
            .all(|&(woman, man, formed)| [woman, man].iter().all(|p| formed - born(*p) >= 16 * Y))
    );
    let partnered = run
        .log
        .iter()
        .filter(|entry| matches!(entry.payload, LogPayload::Partnered { .. }))
        .count();
    assert_eq!(partnered, 17);
    assert_eq!(run.save(), hex(MARKET_SAVE_END_OF_YEAR_39));
    let hashes: Vec<u64> = run.out.year_hashes.iter().map(|year| year.hash).collect();
    assert_eq!(hashes, MARKET_YEAR_HASHES);
    assert_eq!(log_hash(&run.log), MARKET_LOG_HASH);
}

/// `ArrangePartnership` below the market age is rejected (ADR-0018 section 1): sim 12 turns
/// 16 in month 223 (second 539 481 600); an arrangement acting a second before is too young,
/// one acting in that second pairs her.
#[test]
fn an_arrangement_needs_the_market_age() {
    let arrange = |woman: u64, man: u64| {
        Input::ArrangePartnership(ArrangePartnership {
            woman: sim(woman),
            man: sim(man),
        })
    };
    let mut run = Run::market();
    run.advance(539_481_598);
    assert_eq!(
        run.world.submit(arrange(12, 11)).err(),
        Some(InputRejected {
            code: RejectCode::PartnerTooYoung
        })
    );
    run.advance(539_481_599);
    run.world.submit(arrange(12, 11)).expect("accepted");
}

fn arranged(stamp: i64, woman: u64, man: u64) -> Run {
    let mut run = Run::market();
    run.advance(stamp);
    run.world
        .submit(Input::ArrangePartnership(ArrangePartnership {
            woman: sim(woman),
            man: sim(man),
        }))
        .expect("accepted");
    run.log.extend(run.world.take_log());
    run
}

fn reloaded(part: Run, data: &Data) -> Run {
    let bytes = part.save();
    let (world, year_hashes) = World::load(&bytes, data.clone()).expect("loads");
    assert_eq!(world.save(&year_hashes).expect("saves"), bytes);
    Run {
        world,
        out: YearOut {
            census: part.out.census,
            year_hashes,
            trace: Vec::new(),
        },
        log: part.log,
    }
}

#[test]
fn an_arrangement_of_kin_forms_and_its_save_loads_and_runs_on() {
    let end = 40 * Y - 1;
    for (stamp, woman, man) in [(575_769_599, 14, 13), (1_214_438_399, 1, 31)] {
        let mut before = Run::market();
        before.advance(stamp);
        let offered = before.world.partner_candidates(sim(woman));
        assert!(offered.contains(&sim(man)), "{woman} {man}");
        assert!(
            before
                .world
                .partner_candidates(sim(man))
                .contains(&sim(woman))
        );
        let mut whole = arranged(stamp, woman, man);
        assert!(whole.pairs().contains(&(woman, man, stamp + 1)));
        whole.advance(end);
        for stop in [stamp, stamp + 1, stamp + Y] {
            let mut part = arranged(stamp, woman, man);
            if stop > stamp {
                part.advance(stop);
            }
            let mut rest = reloaded(part, &market_data(1.0));
            rest.advance(end);
            assert_eq!(
                rest.out.year_hashes, whole.out.year_hashes,
                "{woman} {stop}"
            );
            assert_eq!(log_hash(&rest.log), log_hash(&whole.log), "{woman} {stop}");
            assert_eq!(rest.world.state_hash(), whole.world.state_hash());
        }
    }
}

fn with_values(values: &[(&str, f64)]) -> Data {
    let (calibration, genome_map) = common::files();
    let mut demography = common::demography();
    for (key, value) in values {
        demography["values"][*key]["value"] = serde_json::json!(value);
    }
    Data::new(common::definitions_with(demography, calibration, genome_map).expect("definitions"))
        .expect("checked")
}

fn aged(founders: &[(i64, Sex)], couples: Vec<Couple>) -> World {
    let mut world = World::new(with_values(&[("core:market_age", 18.0)]));
    world
        .submit(Input::Start(Start {
            world_seed: 0x18,
            founder_tag: DataId::new("test:aged").expect("valid"),
            world_params: WorldParams {
                hereditary_diseases: false,
                nutrition: Vec::new(),
            },
            founders: (founders.iter())
                .map(|&(born, sex)| Founder {
                    born: SimTime::from_secs(born),
                    sex,
                    alleles: Vec::new(),
                })
                .collect(),
            couples,
            capacity: None,
            pool: None,
        }))
        .expect("accepted");
    world.take_log();
    world
}

#[test]
fn an_arrangement_needs_the_towns_market_age() {
    const DAY: i64 = 86_400;
    let founders = [
        (-20 * Y, Sex::Female),
        (-16 * Y, Sex::Male),
        (-18 * Y + DAY, Sex::Male),
        (-18 * Y, Sex::Male),
        (-20 * Y, Sex::Female),
        (-22 * Y, Sex::Male),
    ];
    let couples = || vec![Couple { woman: 4, man: 5 }];
    let arrange = |woman: u64, man: u64| {
        Input::ArrangePartnership(ArrangePartnership {
            woman: sim(woman),
            man: sim(man),
        })
    };
    let mut world = aged(&founders, couples());
    for (woman, man, code) in [
        (1, 2, RejectCode::PartnerTooYoung),
        (1, 3, RejectCode::PartnerTooYoung),
        (1, 6, RejectCode::AlreadyPartnered),
        (5, 4, RejectCode::AlreadyPartnered),
    ] {
        assert_eq!(
            world.submit(arrange(woman, man)).err(),
            Some(InputRejected { code }),
            "{woman} {man}"
        );
    }
    assert_eq!(world.input_log().len(), 1);
    assert_eq!(world.partner_candidates(sim(1)), [sim(4)]);
    assert_eq!(world.partner_candidates(sim(4)), [sim(1)]);
    for young in [2, 3] {
        assert!(world.partner_candidates(sim(young)).is_empty());
    }
    world.submit(arrange(1, 4)).expect("accepted");
    let mut world = aged(&founders, couples());
    world.advance_until(
        &mut YearOut::default(),
        SimTime::from_secs(DAY - 1),
        &mut |_| false,
    );
    assert_eq!(world.partner_candidates(sim(3)), [sim(1)]);
    world.submit(arrange(1, 3)).expect("accepted");
}

fn relabelled(bytes: &[u8], from: &Data, to: &Data) -> Vec<u8> {
    let old = postcard::to_allocvec(&from.hash()).expect("encodes");
    let new = postcard::to_allocvec(&to.hash()).expect("encodes");
    let at = (bytes[..32].windows(old.len()))
        .position(|window| window == old.as_slice())
        .expect("the data hash in the header");
    [&bytes[..at], new.as_slice(), &bytes[at + old.len()..]].concat()
}

#[test]
fn a_partnership_the_market_formed_needs_the_kinship_limit() {
    let blind = |limit: f64| {
        with_values(&[
            ("core:market_search_height_female", 1.0),
            ("core:pairing_cousin_odds", 1.0),
            ("core:pairing_kinship_limit", limit),
        ])
    };
    let data = blind(1.0);
    let mut world = World::new(data.clone());
    world.submit(market_start()).expect("accepted");
    let mut out = YearOut::default();
    world.advance_until(&mut out, SimTime::from_secs(40 * Y - 1), &mut |_| false);
    world.take_log();
    let pedigree = world.pedigree();
    let close = (pedigree.partnerships.iter())
        .filter(|couple| couple.formed.as_secs() > 0 && couple.kinship >= 0.125);
    assert!(close.count() > 0, "a market partnership of close kin");
    let bytes = world.save(&out.year_hashes).expect("saves");
    assert!(World::load(&bytes, data.clone()).is_ok());
    let limited = blind(0.125);
    assert_eq!(
        World::load(&relabelled(&bytes, &data, &limited), limited).err(),
        Some(LoadError::Inconsistent)
    );
}

/// A mother and her son under 16, both single, get `PartnerTooYoung`. Founder 8 and her son
/// 20 at second 183 859 199, by the reference (`tools/world_reference.py`, the first such
/// pair).
#[test]
fn an_arrangement_too_young_and_in_direct_line_is_too_young() {
    let mut run = Run::market();
    run.advance(183_859_199);
    let arranged = Input::ArrangePartnership(ArrangePartnership {
        woman: sim(8),
        man: sim(20),
    });
    assert_eq!(
        run.world.submit(arranged).err(),
        Some(InputRejected {
            code: RejectCode::PartnerTooYoung
        })
    );
}

/// The partners offered to a person come nearest in age first (Grok's round 33, P3): by the
/// difference of their whole years at the last closed second, then the smaller id. At the
/// first second the single founders are, by hand from `market_start`, the women 7 (20 years)
/// and 8 (21) and the men 9 (25) and 10 (40): by id the man of 40 would get 7 first, by age
/// he gets 8 (19 years apart, 7 is 20). The ages of the living are their whole years then.
#[test]
fn offers_come_nearest_in_age_first_with_the_ages_of_the_living() {
    let mut run = Run::market();
    run.advance(0);
    let offered = |n: u64| -> Vec<u64> {
        let list = run.world.partner_candidates(sim(n));
        list.iter().map(|partner| partner.get()).collect()
    };
    assert_eq!(offered(10), [8, 7]);
    assert_eq!(offered(9), [8, 7]);
    assert_eq!(offered(7), [9, 10]);
    assert_eq!(offered(8), [9, 10]);
    let ages: Vec<(u64, i64)> = (run.world.ages().iter())
        .map(|age| (age.sim.get(), age.age_years))
        .collect();
    assert_eq!(
        ages,
        [
            (1, 20),
            (2, 24),
            (3, 21),
            (4, 25),
            (5, 22),
            (6, 23),
            (7, 20),
            (8, 21),
            (9, 25),
            (10, 40)
        ]
    );
}

/// Ties and fractions of the order (Grok's round 33, P3), by hand: at the first second a
/// single man of 30 years (sim 1) and single women of 28 (sim 2) and 32 (sim 3), two years
/// apart on either side; of 31 years and 354 days (sim 4: 31 completed, one apart, though
/// 1.97 years in seconds); of 28 years and 300 days (sim 5: 28 completed, two apart, though
/// 1.18 years in seconds); and one whose 29th birthday is the next, open second (sim 6: 28
/// completed). By completed years: 4, then 2, 3, 5 and 6 by id.
#[test]
fn offers_tie_by_id_and_count_completed_years() {
    const DAY: i64 = 86_400;
    let founder = |born: i64, sex: Sex| Founder {
        born: SimTime::from_secs(born),
        sex,
        alleles: Vec::new(),
    };
    let mut world = World::new(market_data(1.0));
    world
        .submit(Input::Start(Start {
            world_seed: 0xff,
            founder_tag: DataId::new("test:offers").expect("valid"),
            world_params: WorldParams {
                hereditary_diseases: false,
                nutrition: Vec::new(),
            },
            founders: vec![
                founder(-30 * Y, Sex::Male),
                founder(-28 * Y, Sex::Female),
                founder(-32 * Y, Sex::Female),
                founder(-31 * Y - 354 * DAY, Sex::Female),
                founder(-28 * Y - 300 * DAY, Sex::Female),
                founder(-29 * Y + 1, Sex::Female),
            ],
            couples: Vec::new(),
            capacity: None,
            pool: None,
        }))
        .expect("accepted");
    world.advance_until(&mut YearOut::default(), SimTime::from_secs(0), &mut |_| {
        false
    });
    let offered: Vec<u64> = (world.partner_candidates(sim(1)).iter())
        .map(|partner| partner.get())
        .collect();
    assert_eq!(offered, [4, 2, 3, 5, 6]);
}

/// Saving and loading between rounds changes nothing: the kinship cache starts empty after
/// a load (ADR-0018 section 2) and every φ comes out the same.
#[test]
fn save_load_continue_across_rounds() {
    let end = 40 * Y - 1;
    let mut whole = Run::market();
    whole.advance(end);
    for stop in [
        MONTH - 1,
        MONTH,
        238 * MONTH,
        478 * MONTH - 1,
        478 * MONTH,
        30 * Y,
    ] {
        let mut part = Run::market();
        part.advance(stop);
        let bytes = part.save();
        let (loaded, years) = World::load(&bytes, market_data(1.0)).expect("loads");
        assert_eq!(loaded.save(&years).expect("saves"), bytes, "stop {stop}");
        let mut rest = Run {
            world: loaded,
            out: YearOut {
                census: part.out.census.clone(),
                year_hashes: years,
                trace: Vec::new(),
            },
            log: part.log,
        };
        rest.advance(end);
        assert_eq!(rest.out.year_hashes, whole.out.year_hashes, "stop {stop}");
        assert_eq!(log_hash(&rest.log), log_hash(&whole.log), "stop {stop}");
        assert_eq!(
            rest.world.state_hash(),
            whole.world.state_hash(),
            "stop {stop}"
        );
    }
}
